#include "an1x_research_machine.h"
#include <cstdio>
#include <functional>
struct Sink{std::vector<std::tuple<unsigned,uint64_t,bool>>txs;std::function<void()>callback;void tx(unsigned c,uint64_t t,bool b){txs.emplace_back(c,t,b);if(callback)callback();}void clock(unsigned,uint64_t,bool){}bool dma_request(unsigned,uint64_t){return false;}uint8_t gpio_read(unsigned,uint64_t){return 0;}void gpio_write(unsigned,uint64_t,uint8_t,uint8_t){}};
using Machine=yamanix::An1xResearchMachine<Sink>;using Policy=Machine::NvramPolicy;
unsigned failures=0;void check(bool b,const char*s){if(!b&&++failures<12)std::fprintf(stderr,"%s\n",s);}
template<class F>void rejects(F f,const char*s){bool bad=false;try{f();}catch(const std::exception&){bad=true;}check(bad,s);}
std::vector<uint8_t> image(){std::vector<uint8_t>r(0x100000);r[2]=1;std::vector<uint16_t>p{0x7a00,0xff,0xffb1,0xfa00,0x688a,0x0b00,0xfa20,0x688a,0x0b00,0xfaa5,0x688a,0x0b00,0x680b,0xeb7f,0x688b,0x40fe};for(unsigned i=0;i<p.size();++i){r[0x100+2*i]=uint8_t(p[i]>>8);r[0x101+2*i]=uint8_t(p[i]);}return r;}
int main(){
 for(unsigned cut=0;cut<=400;++cut){auto r=image();Sink sa,sb;Machine a(r,{},sa),b(r,{},sb);a.run(int(cut),10000);a.write_byte(0x200000,0x5a);a.write_byte(0xfffd10,0xa5);a.write_byte(0xfffff2,1);a.write_byte(0xfffff5,0xff);auto saved=a.nvram_image();a.cold_restart(Policy::preserve);check(a.generation()==1&&a.cycle()==0&&!a.failed()&&a.nvram_image()==saved,"401 mid-instruction/debt/peripheral restarts preserve NVRAM and zero time");check(a.snapshot()==b.snapshot()&&a.read_byte(0xfffd10)==0&&a.read_byte(0xfffff2)==9&&a.read_byte(0xfffff5)==0&&a.read_byte(0xffffb1)==0xff,"Fresh CPU/internalRAM/SYSCR/IRQ/SCI state before execution");sa.txs.clear();a.run(400,10000);b.run(400,10000);check(a.snapshot()==b.snapshot()&&sa.txs==sb.txs,"401 restarted CPU and wire histories match independent fresh epoch");}
 {auto r=image();Sink s;Machine m(r,{},s);for(unsigned i=0;i<262144;++i)m.write_byte(0x200000+i,uint8_t((i*37)^0x5a));auto saved=m.nvram_image();for(unsigned n=0;n<8;++n){m.cold_restart(Policy::preserve);check(m.nvram_image()==saved&&m.generation()==n+1,"Complete256KiB NVRAM retained across repeated epochs");}m.cold_restart(Policy::clear);auto zero=m.nvram_image();check(std::all_of(zero.begin(),zero.end(),[](auto b){return b==0;}),"Explicit clear discards all NVRAM");}
 {auto r=image();Sink s;Machine m(r,{},s);m.run(31,1000);auto before=m.snapshot();auto gen=m.generation();std::vector<Machine::RxEvent>bad{{2,0,false},{1,0,true}};rejects([&]{m.cold_restart(Policy::clear,bad);},"Unsorted replacement input rejected before swap");check(m.snapshot()==before&&m.generation()==gen&&m.cycle()==31&&!m.failed(),"Invalid restart preserves old live epoch");rejects([&]{m.cold_restart(Policy(99));},"Unknown NVRAM policy rejected");m.run(369,10000);}
 {auto r=image();Sink s;Machine m(r,{},s);m.write_byte(0x200000,0x91);rejects([&]{m.run(400,0);},"Execution-limit failure poisons epoch");check(m.failed(),"Failed CPU retained until reconstruction");rejects([&]{m.run(1,100);},"Failed epoch cannot resume");m.cold_restart(Policy::preserve);check(!m.failed()&&m.read_byte(0x200000)==0x91&&m.cycle()==0,"Cold reconstruction recovers with explicit persistent RAM");m.run(400,10000);}
 {auto r=image();Sink s;Machine m(r,{},s);s.callback=[&]{try{m.cold_restart(Policy::clear);}catch(const std::logic_error&) {}};rejects([&]{m.run(400,10000);},"Suppressed callback restart still poisons outer execution");check(m.failed()&&m.generation()==0,"Reentry never destroys active CPU/bus");s.callback={};m.cold_restart(Policy::clear);m.run(400,10000);check(!m.failed(),"Recovery uses new epoch after reentry");}
 {auto r=image();Sink sa,sb;Machine a(r,{},sa),b(r,{},sb);r[0x101]^=0xff;a.write_byte(0x200000,1);a.cold_restart(Policy::preserve);a.run(400,10000);b.run(400,10000);check(a.snapshot()==b.snapshot()&&sa.txs==sb.txs&&b.read_byte(0x200000)==0,"Owned immutable ROM survives caller mutation;machines isolated");}
 {auto r=image();Sink s;std::vector<Machine::RxEvent>edges{{1000,0,false}};Machine m(r,edges,s);m.run(1100,10000);check(m.consumed_input()==1,"Original RX schedule consumed in first epoch");m.cold_restart(Policy::clear);m.run(1100,10000);check(!m.failed()&&m.consumed_input()==0,"Old pending input discarded when replacement schedule empty");std::vector<Machine::RxEvent>next{{0,1,false},{10,1,true}};m.cold_restart(Policy::preserve,next);next[0].channel=99;m.run(400,10000);check(m.consumed_input()==2&&!m.failed(),"Replacement RX schedule is epoch-relative and copied before caller mutation");}
 std::printf("Research lifecycle:401 partial/debt restarts,full NVRAM persistence/clear,invalid-input strong replacement,failed/reentrant epoch recovery,ROM/owner isolation:%u failures\n",failures);return failures?1:0;
}
